import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:liveview_flutter/live_view/live_view.dart';

import '../test_helpers.dart';

final Map<String, dynamic> RENDERED_MAP =
    jsonDecode(RENDERED) as Map<String, dynamic>;
final Map<String, dynamic> SEARCH_DIFF_MAP =
    jsonDecode(SEARCH_DIFF) as Map<String, dynamic>;

// Reproduces the settings currency search: the server sends a diff that
// updates the currency_input dropdown inside a Form > Stack; the client
// must apply it.
main() async {
  testWidgets('applies the currency search diff inside a Form + Stack', (
    tester,
  ) async {
    tester.view.physicalSize = const Size(1600, 1200);
    tester.view.devicePixelRatio = 1.0;
    addTearDown(tester.view.reset);
    var (view, _) = await connect(LiveView());
    await tester.runLiveView(view);

    view.handleRenderedMessage(RENDERED_MAP);
    await tester.pump();

    expect(find.text('EUR (€)'), findsOneWidget);
    expect(find.text(r'AUD (A$)'), findsNothing);

    view.handleDiffMessage(SEARCH_DIFF_MAP);
    await tester.pump(const Duration(milliseconds: 1));
    await tester.pump(const Duration(milliseconds: 1));

    expect(find.text(r'AUD (A$)'), findsWidgets);
    expect(find.text('Australian Dollar'), findsWidgets);
  });
}

